style.css:
@-moz-document domain("discord.com") {
:root {
        /* Colores de Fondo (Rosa Pastel Suave) */
        --background-primary: #FFF0F5 !important;    /* Fondo del chat */
        --background-secondary: #FFE4E1 !important;  /* Lista de canales */
        --background-tertiary: #FFD1DC !important;   /* Barra de servidores */
        --background-floating: #FFF0F5 !important;   /* Menús flotantes */
        
        /* Caja donde escribes los mensajes */
        --channeltextarea-background: #FFE4E1 !important;
        --background-secondary-alt: #FFD1DC !important;

        /* NUEVOS COLORES DE TEXTO (Rosa Pastel más Oscuro / Tonos Frambuesa y Rosa Viejo) */
        --text-normal: #A94A6E !important;          /* Letras de los chats */
        --text-muted: #C7829B !important;           /* Letras secundarias o explicaciones */
        --header-primary: #83254A !important;       /* Nombres de los usuarios y títulos */
        --header-secondary: #9B3861 !important;     /* Subtítulos generales */
        --channels-default: #A94A6E !important;     /* Nombres de canales normales */
        
        /* Detalles, Enlaces y Botones */
        --brand-experiment: #FF69B4 !important;     /* Botones principales */
        --text-link: #C71585 !important;            /* Enlaces web (Rosa medio-oscuro) */
        --interactive-normal: #A94A6E !important;   /* Iconos de la interfaz */
        --interactive-hover: #83254A !important;    /* Iconos al pasar el mouse */
        --interactive-active: #FF69B4 !important;   /* Iconos seleccionados */
    }

    /* Fondo especial suave al pasar el mouse sobre un mensaje */
    [class*="message-"] {
        background-color: transparent !important;
    }
    [class*="message-"]:hover {
        background-color: rgba(255, 105, 180, 0.08) !important;
    }
}

